function kruskal(nodeCount, edges) {
  const parent = Array.from({ length: nodeCount }, (_, i) => i);

  function find(x) {                       // which group is x in?
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];       // flatten as we walk
      x = parent[x];
    }
    return x;
  }

  function union(a, b) {                   // merge two groups
    const ra = find(a), rb = find(b);
    if (ra === rb) return false;           // already together, this edge is a cycle
    parent[ra] = rb;
    return true;
  }

  const sorted = [...edges].sort((x, y) => x.weight - y.weight);
  const tree = [];

  for (const edge of sorted) {
    if (union(edge.from, edge.to)) tree.push(edge);
    if (tree.length === nodeCount - 1) break;   // a tree is full
  }

  return tree;
}
